/* A OnePage names only its own owner's store (round AW, database security). onepages.seller_id and creator_id say whose store a page belongs to, and the app trusts them: the address storelib.me/{username} serves the published page that names that account's store (lib/onepage/address-lookup.ts pageOfAccount), the page's ban check, indexing and link following read that store (lib/onepage/published-page.ts onePageOwner: a banned owner's page is withheld, and a page whose store sells nothing gets nofollow links), and tips, sign ups and analytics go to it. The owner policy on onepages checks only owner_id, so with the public key anybody could point their own page at another creator's store: their page could then answer at that creator's address, stay up after their own ban, and pass for a store that sells. Now a write with the browser key (anon or authenticated) may set seller_id and creator_id only to a store the page's owner owns (creators.user_id = owner_id), or to the owner's own account id, which the older onboarding wrote into seller_id; any other value keeps the old one on an update and is left empty on a new row, and the server fills an empty one with the owner's store as it already does (app/api/onepage/route.ts, lib/onepage/ensure-onepage.ts). The helper public.storelib_store_of_owner(uuid, uuid) runs with its owner's rights and says only whether that account owns that store, which the public columns of creators already show. It does NOT change any row: to see pages that already name another login's store, select o.id, o.slug, o.owner_id, o.seller_id, o.creator_id from public.onepages o where (o.seller_id is not null and not public.storelib_store_of_owner(o.seller_id, o.owner_id)) or (o.creator_id is not null and not public.storelib_store_of_owner(o.creator_id, o.owner_id)). The service role writes as before. Skipped with a notice where onepages or one of its seller_id, creator_id and owner_id columns is not here (seller_id comes with part 165). LOCKS: CREATE TRIGGER takes a short lock on onepages, held until the paste ends. Safe to run again. */
CREATE OR REPLACE FUNCTION public.storelib_store_of_owner(p_store uuid, p_owner uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $f$ SELECT p_store IS NOT NULL AND p_owner IS NOT NULL AND (p_store = p_owner OR EXISTS (SELECT 1 FROM public.creators c WHERE c.id = p_store AND c.user_id = p_owner)) $f$;
REVOKE ALL ON FUNCTION public.storelib_store_of_owner(uuid, uuid) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.storelib_store_of_owner(uuid, uuid) TO authenticated, service_role;
CREATE OR REPLACE FUNCTION public.onepages_own_store_only() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $f$ BEGIN IF current_user NOT IN ('authenticated', 'anon') THEN RETURN NEW; END IF; IF TG_OP = 'INSERT' THEN IF NEW.seller_id IS NOT NULL AND NOT public.storelib_store_of_owner(NEW.seller_id, NEW.owner_id) THEN NEW.seller_id := NULL; END IF; IF NEW.creator_id IS NOT NULL AND NOT public.storelib_store_of_owner(NEW.creator_id, NEW.owner_id) THEN NEW.creator_id := NULL; END IF; ELSE IF NEW.seller_id IS DISTINCT FROM OLD.seller_id AND NEW.seller_id IS NOT NULL AND NOT public.storelib_store_of_owner(NEW.seller_id, NEW.owner_id) THEN NEW.seller_id := OLD.seller_id; END IF; IF NEW.creator_id IS DISTINCT FROM OLD.creator_id AND NEW.creator_id IS NOT NULL AND NOT public.storelib_store_of_owner(NEW.creator_id, NEW.owner_id) THEN NEW.creator_id := OLD.creator_id; END IF; END IF; RETURN NEW; END $f$;
REVOKE ALL ON FUNCTION public.onepages_own_store_only() FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.onepages') IS NULL THEN RAISE NOTICE 'part 453: public.onepages does not exist here, skipped'; RETURN; END IF; IF (SELECT count(*) FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'onepages' AND column_name IN ('seller_id', 'creator_id', 'owner_id')) < 3 THEN RAISE NOTICE 'part 453: public.onepages lacks seller_id, creator_id or owner_id here (seller_id comes with part 165), skipped'; RETURN; END IF; DROP TRIGGER IF EXISTS onepages_own_store_only ON public.onepages; CREATE TRIGGER onepages_own_store_only BEFORE INSERT OR UPDATE OF seller_id, creator_id, owner_id ON public.onepages FOR EACH ROW EXECUTE FUNCTION public.onepages_own_store_only(); END $do$;
notify pgrst, 'reload schema';
